// Function names for code addresses, and backtraces (backtrace.h).

#include <backtrace.h>
#include <cpu.h>
#include <kprintf.h>
#include <memory.h>
#include <stdbool.h>
#include <stddef.h>
#include <vmm.h>

// The symbol table, generated by scripts/mksyms.py into the .ksyms
// section: every function in .text, sorted by address.
struct ksym {
    uint64_t addr;
    uint64_t name; // offset in ksyms_names
};

extern const uint64_t ksyms_count;
extern const struct ksym ksyms_table[];
extern const char ksyms_names[];
extern char text_start[], text_end[];

#define MAX_FRAMES  16
#define KERNEL_HALF 0xffff800000000000ull
#define PTE_ADDR    0x000ffffffffff000ull

const char *symbolize(uint64_t addr, uint64_t *offset) {
    if (addr < (uint64_t)text_start || addr >= (uint64_t)text_end) return NULL;
    // The last symbol at or below `addr`.
    size_t lo = 0, hi = ksyms_count;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (ksyms_table[mid].addr <= addr) lo = mid + 1;
        else hi = mid;
    }
    if (lo == 0) return NULL;
    *offset = addr - ksyms_table[lo - 1].addr;
    return ksyms_names + ksyms_table[lo - 1].name;
}

static void print_frame(int depth, uint64_t addr, uint64_t lookup) {
    uint64_t offset;
    const char *name = symbolize(lookup, &offset);
    if (name) kprintf("    #%d %p %s+0x%lx\n", depth, (void *)addr, name, offset + (addr - lookup));
    else kprintf("    #%d %p\n", depth, (void *)addr);
}

// Whether `virt` is mapped in the page tables in use. Reads them through
// the HHDM, so before pmm_init() there's no telling: say yes, and let the
// crash screen's guard against faulting in itself (smp_panic_begin) catch it.
static bool mapped(uint64_t virt) {
    if (!hhdm_offset) return true;
    struct vmm_space space = {.pml4 = read_cr3() & PTE_ADDR};
    uint64_t phys;
    return vmm_virt_to_phys(&space, virt, &phys);
}

void backtrace_print(uint64_t rip, uint64_t rbp) {
    kprintf("  backtrace:\n");
    int depth = 0;
    if (rip) print_frame(depth++, rip, rip);
    for (; depth < MAX_FRAMES && rbp; depth++) {
        // A frame is the caller's saved %rbp, then the return address.
        const char *bad = rbp < KERNEL_HALF ? "is not a kernel address"
                          : rbp & 7         ? "is not aligned"
                          : rbp > UINT64_MAX - 16 || !mapped(rbp) || !mapped(rbp + 15) ? "is not mapped"
                                                                                       : NULL;
        if (bad) {
            kprintf("    stopped: frame pointer %p %s\n", (void *)rbp, bad);
            return;
        }
        const uint64_t *frame = (const uint64_t *)rbp;
        uint64_t ret = frame[1];
        if (ret == 0) return;
        // The call is just before the return address, which may already be
        // in the next function when the call was the last instruction.
        print_frame(depth, ret, ret - 1);
        // Callers' frames are further up the stack: anything else is a loop.
        if (frame[0] && frame[0] <= rbp) {
            kprintf("    stopped: frame pointer %p is below the last one\n", (void *)frame[0]);
            return;
        }
        rbp = frame[0];
    }
}
